def string_sequence(n: int) -> str:
    if n < 0:
        return ''
    return ' '.join(str(i) for i in range(n + 1))

def count_distinct_characters(string: str) -> int:
    """
    Find out how many distinct characters (regardless of case) are in the string.
    """
    return len(set(string.lower()))

def sort_numbers(numbers: str) -> str:
    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }
    num_to_word = {v: k for k, v in word_to_num.items()}

    words = numbers.split()
    nums = [word_to_num[w] for w in words]
    nums.sort()

    return ' '.join(num_to_word[n] for n in nums)

def largest_divisor(n: int) -> int:
    """
    Find the largest number that divides n evenly, smaller than n.
    Return -1 if such a number does not exist.
    """
    if n <= 1:
        return -1

    for i in range(n - 1, 0, -1):
        if n % i == 0:
            return i

    return -1

"""
String case manipulation utilities.
"""


def flip_case(string: str) -> str:
    """
    For a given string, flip lowercase characters to uppercase and uppercase to lowercase.

    Example:
        >>> flip_case('Hello')
        'hELLO'
    """
    if not string:
        return string

    result_chars = []
    for char in string:
        if char.islower():
            result_chars.append(char.upper())
        elif char.isupper():
            result_chars.append(char.lower())
        else:
            result_chars.append(char)

    return ''.join(result_chars)

