def fizz_buzz(n: int) -> int:
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def encode_cyclic(s: str) -> str:
    """
    Returns encoded string by cycling groups of three characters.
    """
    groups = [s[(3 * i):min((3 * i + 3), len(s))]
              for i in range((len(s) + 2) // 3)]
    groups = [(group[1:] + group[0]) if len(group)
              == 3 else group for group in groups]
    return "".join(groups)


def decode_cyclic(s: str) -> str:
    """
    Takes as input string encoded with encode_cyclic function. Returns decoded string.
    """
    groups = [s[(3 * i):min((3 * i + 3), len(s))]
              for i in range((len(s) + 2) // 3)]
    decoded_groups = []
    for group in groups:
        if len(group) == 3:
            decoded_group = group[-1] + group[:-1]
            decoded_groups.append(decoded_group)
        else:
            decoded_groups.append(group)
    return "".join(decoded_groups)

def is_prime(num: int) -> bool:
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True

def prime_fib(n: int) -> int:
    if n <= 0:
        return 0
    count = 0
    a, b = 0, 1
    while True:
        a, b = b, a + b
        if a > 1 and is_prime(a):
            count += 1
            if count == n:
                return a

def change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    while x > 0:
        digits.append(str(x % base))
        x //= base
    return ''.join(reversed(digits))

def fib4(n: int) -> int:
    if n < 2:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    a, b, c, d = 0, 0, 2, 0
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d

    return d

def is_palindrome(text: str) -> bool:
    cleaned = ''.join(ch.lower() for ch in text if ch.isalnum())
    return cleaned == cleaned[::-1]

def decode_shift(s: str) -> str:
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            shifted = chr((ord(ch) - ord('a') - 5) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(ch)
    return ''.join(result)

def remove_vowels(text: str) -> str:
    vowels = "aeiouAEIOU"
    return "".join(char for char in text if char not in vowels)

def same_chars(s0: str, s1: str) -> bool:
    """
    Check if two words have the same characters.
    """
    return sorted(s0) == sorted(s1)

def fib(n: int) -> int:
    if n <= 0:
        return 0
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def correct_bracketing(brackets: str) -> bool:
    balance = 0
    for char in brackets:
        if char == "<":
            balance += 1
        elif char == ">":
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def largest_prime_factor(n: int) -> int:
    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            n //= factor
        else:
            factor += 1 if factor == 2 else 2
    return n

def sum_to_n(n: int) -> int:
    if n <= -1:
        return 0
    if n == 0:
        return 1
    return n * (n + 1) // 2

def correct_bracketing(brackets: str) -> bool:
    balance = 0
    for char in brackets:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def fibfib(n: int) -> int:
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1

    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c

def vowels_count(s: str) -> int:
    vowels = set('aeiou')
    s = s.strip()
    count = 0
    for i, ch in enumerate(s):
        if ch.lower() in vowels:
            count += 1
        elif ch.lower() == 'y' and i == len(s) - 1:
            count += 1
    return count

from typing import List

def pluck(arr: List[int]) -> List[int]:
    if not arr:
        return []

    smallest_even = None
    smallest_index = -1

    for i, num in enumerate(arr):
        if num % 2 == 0:
            if smallest_even is None or num < smallest_even or (num == smallest_even and i < smallest_index):
                smallest_even = num
                smallest_index = i

    if smallest_even is None:
        return []

    return [smallest_even, smallest_index]

from typing import List


def search(lst: List[int]) -> int:
    """
    Return the greatest integer that is greater than zero and has a frequency
    greater than or equal to the integer's value. If no such value exists,
    return -1.

    Args:
        lst: A non-empty list of positive integers.

    Returns:
        The greatest integer meeting the criteria, or -1 if none exists.
    """
    frequency = {}
    for num in lst:
        frequency[num] = frequency.get(num, 0) + 1

    candidates = []
    for num, count in frequency.items():
        if num > 0 and count >= num:
            candidates.append(num)

    if not candidates:
        return -1

    return max(candidates)

