def triangle_area(a: int, b: int, c: int) -> float:
    if a + b > c and a + c > b and b + c > a:
        s = (a + b + c) / 2
        area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
        return round(area, 2)
    else:
        return -1

from typing import List

def total_match(lst1: List[str], lst2: List[str]) -> List[str]:
    total1 = sum(len(s) for s in lst1)
    total2 = sum(len(s) for s in lst2)
    if total1 <= total2:
        return lst1
    else:
        return lst2

def is_multiply_prime(a: int) -> bool:
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [i for i in range(2, 101) if is_prime(i)]

    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False

def is_multiply_prime(a: int) -> bool:
    """
    Check if the given number is the multiplication of 3 prime numbers.

    Constraints:
        The three prime numbers must be <= 100.

    Example:
        is_multiply_prime(30) == True
        30 = 2 * 3 * 5
    """
    if a <= 1:
        return False

    # Generate primes up to 100 using Sieve of Eratosthenes
    sieve = [True] * 101
    sieve[0] = sieve[1] = False
    for i in range(2, int(101**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, 101, i):
                sieve[j] = False
    primes = [i for i, is_prime in enumerate(sieve) if is_prime]

    # Check all combinations of three primes
    n = len(primes)
    for i in range(n):
        for j in range(i, n):
            for k in range(j, n):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False

def is_simple_power(x: int, n: int) -> bool:
    if n == 1:
        return x == 1
    if x == 1:
        return True
    power = 0
    current = 1
    while current <= x:
        if current == x:
            return True
        power += 1
        current *= n
    return False

def is_simple_power(x: int, n: int) -> bool:
    """
    Check if number x is a simple power of n.
    x is a simple power of n if n to the power of some integer equals x.
    """
    if n == 0:
        return x == 0
    if n == 1:
        return x == 1
    if x == 1:
        return True
    if n == -1:
        return x == 1 or x == -1

    exponent = 0
    power = 1
    while True:
        if power == x:
            return True
        exponent += 1
        power *= n
        if abs(power) > abs(x) and exponent > 0:
            break
    return False

def iscube(a: int) -> bool:
    if a < 0:
        return (-(-a) ** (1/3)).is_integer()
    return (a ** (1/3)).is_integer()

def hex_key(num: str) -> int:
    primes = {'2', '3', '5', '7', 'B', 'D'}
    return sum(1 for digit in num if digit in primes)

def decimal_to_binary(decimal: int) -> str:
    binary_str = ""
    while decimal > 0:
        binary_str = str(decimal % 2) + binary_str
        decimal //= 2
    return "db" + (binary_str if binary_str else "0") + "db"

def is_happy(s: str) -> bool:
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i + 1] or s[i] == s[i + 2] or s[i + 1] == s[i + 2]:
            return False
    return True

from typing import List


def numerical_letter_grade(grades: List[float]) -> List[str]:
    def round_half_up(n: float) -> float:
        if n < 0:
            return -round_half_up(-n)
        # Add a small epsilon to handle floating point precision issues
        eps = 1e-6
        int_part = int(n)
        frac_part = n - int_part
        if frac_part >= 0.5 - eps:
            return int_part + 1.0
        else:
            return float(int_part)

    result = []
    for grade in grades:
        if grade < 0.0 or grade > 4.0:
            result.append('')
            continue

        # Round to 1 decimal place using half-up
        rounded = round_half_up(grade * 10) / 10.0

        # Apply tolerance
        eps = 1e-6
        if abs(rounded - 4.0) < eps:
            result.append('A+')
        elif rounded > 3.7 - eps:
            result.append('A')
        elif rounded > 3.3 - eps:
            result.append('A-')
        elif rounded > 3.0 - eps:
            result.append('B+')
        elif rounded > 2.7 - eps:
            result.append('B')
        elif rounded > 2.3 - eps:
            result.append('B-')
        elif rounded > 2.0 - eps:
            result.append('C+')
        elif rounded > 1.7 - eps:
            result.append('C')
        elif rounded > 1.3 - eps:
            result.append('C-')
        elif rounded > 1.0 - eps:
            result.append('D+')
        elif rounded > 0.7 - eps:
            result.append('D')
        elif rounded > 0.0 - eps:
            result.append('D-')
        else:
            result.append('E')

    return result

from typing import List


def numerical_letter_grade(grades: List[float]) -> List[str]:
    """
    Convert numerical GPAs to letter grades according to the specified grading scale.

    The GPA is first rounded to one decimal place using half-up rounding,
    then converted to a letter grade using the provided table.
    For GPAs outside the valid range (0.0 to 4.0), an empty string is returned.

    Args:
        grades: List of float GPAs, each with one decimal place.

    Returns:
        List of corresponding letter grades.
    """
    def round_half_up(num: float) -> float:
        """Round to one decimal place using half-up method."""
        return round(num + 1e-6, 1)

    def gpa_to_letter(gpa: float) -> str:
        """Convert a single GPA to letter grade."""
        if not 0.0 <= gpa <= 4.0:
            return ''

        if gpa == 4.0:
            return 'A+'
        elif gpa > 3.7:
            return 'A'
        elif gpa > 3.3:
            return 'A-'
        elif gpa > 3.0:
            return 'B+'
        elif gpa > 2.7:
            return 'B'
        elif gpa > 2.3:
            return 'B-'
        elif gpa > 2.0:
            return 'C+'
        elif gpa > 1.7:
            return 'C'
        elif gpa > 1.3:
            return 'C-'
        elif gpa > 1.0:
            return 'D+'
        elif gpa > 0.7:
            return 'D'
        elif gpa > 0.0:
            return 'D-'
        else:  # gpa == 0.0
            return 'E'

    return [gpa_to_letter(round_half_up(g)) for g in grades]
